package ai.eva.android.probe;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.view.*;import android.webkit.*;import org.json.*;import java.io.*;import java.nio.file.*;import java.util.concurrent.*;

/** Own fixture only; no third-party upload. Verifies a real WebView File input reads the selected URI. */
public final class BrowserTransfersCheck extends BrowserWindowCheck {
 String web(BrowserWindow b,String script)throws Exception{CompletableFuture<String> f=new CompletableFuture<>();runOnMainSync(()->b.browser.evaluateJavascript(script,f::complete));return f.get(5,TimeUnit.SECONDS);}
 void tapInput(BrowserWindow b)throws Exception{JSONObject box=new JSONObject(web(b,"(()=>{const r=document.querySelector('input').getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2,width:innerWidth}})()"));int[] pos=new int[2],width=new int[1];runOnMainSync(()->{b.browser.getLocationOnScreen(pos);width[0]=b.browser.getWidth();});float scale=(float)(width[0]/box.getDouble("width"));float x=pos[0]+(float)box.getDouble("x")*scale,y=pos[1]+(float)box.getDouble("y")*scale;long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,x,y,0),up=MotionEvent.obtain(now,now+60,MotionEvent.ACTION_UP,x,y,0);try{sendPointerSync(down);sendPointerSync(up);}finally{down.recycle();up.recycle();}}
 @Override public void onStart(){Bundle out=new Bundle();int code=0;BrowserWindow browser=null;Uri selected=null;BrowserTransfers.Transfer download=null;
  try{
   ShellActivity shell=(ShellActivity)startActivitySync(new Intent(getTargetContext(),ShellActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(shell,"typeof navigate==='function'&&!!document.querySelector('[data-action=drawer]')");runOnMainSync(()->shell.showBrowser(new Intent()));browser=BrowserWindow.live;BrowserWindow b=browser;
   runOnMainSync(()->{b.browser.loadDataWithBaseURL("https://eva-browser-test.invalid/","<meta name=viewport content='width=device-width'><h1>Upload acceptance</h1><input type=file accept='text/plain' style='width:90%;height:80px' onchange=\"this.files[0].text().then(t=>document.querySelector('h1').textContent=t)\">","text/html","UTF-8",null);b.windowMode(false,false);});Thread.sleep(500);
   ContentValues values=new ContentValues();values.put(MediaStore.Downloads.DISPLAY_NAME,"EvaBrowserUpload-"+java.util.UUID.randomUUID()+".txt");values.put(MediaStore.Downloads.MIME_TYPE,"text/plain");values.put(MediaStore.Downloads.RELATIVE_PATH,"Download/EvaAcceptance");selected=shell.getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);if(selected==null)throw new Exception("Fixture URI unavailable");try(OutputStream output=shell.getContentResolver().openOutputStream(selected)){output.write("EVA_UPLOAD_7391".getBytes("UTF-8"));}
   tapInput(b);long until=SystemClock.elapsedRealtime()+3000;while(b.transfers.upload==null&&SystemClock.elapsedRealtime()<until)Thread.sleep(50);if(b.transfers.upload==null)throw new Exception("WebView file chooser was not invoked");Uri selection=selected;runOnMainSync(()->{if(b.transfers.uploadPrompt!=null)b.transfers.uploadPrompt.dismiss();b.transfers.finishUpload(Activity.RESULT_OK,new Intent().setData(selection));});
   until=SystemClock.elapsedRealtime()+5000;boolean uploaded=false;while(SystemClock.elapsedRealtime()<until){if("true".equals(web(b,"document.querySelector('h1').textContent==='EVA_UPLOAD_7391'"))){uploaded=true;break;}Thread.sleep(50);}if(!uploaded)throw new Exception("Selected URI not readable by HTML File input");out.putString("upload","PASS real WebView File input reads selected own MediaStore URI; picker result injected, system picker UI not automated");
   BrowserTransfers.Transfer task=new BrowserTransfers.Transfer("https://example.com/",new JSONArray("["+web(b,"navigator.userAgent")+"]").getString(0),"https://example.com","https://example.com","eva-download-acceptance.html",-1);download=task;runOnMainSync(()->{b.transfers.items.add(0,task);b.transfers.start(task);});until=SystemClock.elapsedRealtime()+30000;while(!task.terminal()&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);if(!task.state.equals("completed"))throw new Exception("HTTPS download failed: "+task.label());File file=WorkspaceFiles.resolve(shell,task.path.substring("/root/eva-workspace/".length()));if(!new String(Files.readAllBytes(file.toPath()),"UTF-8").contains("Example Domain"))throw new Exception("Downloaded fixture content mismatch");out.putString("download","PASS HTTPS response saved in workspace; "+task.received+" bytes");
   BrowserTransfers.Transfer cancelled=new BrowserTransfers.Transfer("https://example.com/","","https://example.com","https://example.com","cancelled.html",-1);cancelled.cancel();runOnMainSync(()->b.transfers.start(cancelled));if(!cancelled.state.equals("cancelled")||cancelled.partial!=null)throw new Exception("Cancelled transfer started");
   runOnMainSync(()->b.windowMode(false,true));Thread.sleep(150);js(shell,"document.querySelector('#phone').classList.remove('drawer-open');true");tap(shell,"[data-action=drawer]");await(shell,"document.querySelector('#phone').classList.contains('drawer-open')");out.putString("touch","PASS minimized browser after upload/download does not intercept conversation touch");out.putString("result","PASS");
  }catch(Exception e){code=1;out.putString("error",e.toString());}
  finally{if(selected!=null)try{getTargetContext().getContentResolver().delete(selected,null,null);}catch(Exception ignored){}if(download!=null&&!download.path.isEmpty())try{File f=WorkspaceFiles.resolve(getTargetContext(),download.path.substring("/root/eva-workspace/".length()));f.delete();f.getParentFile().delete();}catch(Exception ignored){}if(browser!=null){BrowserWindow b=browser;runOnMainSync(b::finish);}}
  finish(code,out);
 }
}
